import java.util.*;

class Solution {
    private List<String> res = new ArrayList<>();

    public List<String> binaryStrings(int n) {
        backtrack(n, new StringBuilder());
        return res;
    }

    private void backtrack(int n, StringBuilder path) {
        if (path.length() == n) {
            res.add(path.toString());
            return;
        }
        for (char c : new char[]{'0', '1'}) {
            path.append(c);                          // choose
            backtrack(n, path);                      // explore
            path.deleteCharAt(path.length() - 1);    // un-choose
        }
    }
}

